import{_ as t,c as r,o as a,a3 as s}from"./chunks/framework.Dokpd4od.js";const u=JSON.parse('{"title":"Manage deals","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/purchase/orders/index.md","filePath":"master/supply-chain/purchase/orders/index.md","lastUpdated":1791902625000}'),o={name:"master/supply-chain/purchase/orders/index.md"};function n(i,e,d,l,h,c){return a(),r("div",null,e[0]||(e[0]=[s(`<h1 id="manage-deals" tabindex="-1">Manage deals <a class="header-anchor" href="#manage-deals" aria-label="Permalink to &quot;Manage deals&quot;">​</a></h1><p>Deals are the heart of Purchase. An order is the document you build to buy goods from a vendor. It starts as a request for quotation (RFQ), becomes a purchase order when you confirm it, and ends as a received and billed deal.</p><blockquote><p><strong>In simple words:</strong> One document, one life. You draft it, send it, confirm it, receive the goods and pay the bill.</p></blockquote><p>Open <code>Purchase → Orders</code>. The menu shows <strong>Request for Quotation</strong>, <strong>Purchase Orders</strong>, <strong>Purchase Agreements</strong> and <strong>Vendors</strong>.</p><h2 id="the-deal-flow" tabindex="-1">The deal flow <a class="header-anchor" href="#the-deal-flow" aria-label="Permalink to &quot;The deal flow&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>RFQ → RFQ Sent → Purchase Order → Locked</span></span>
<span class="line"><span> │        │            │</span></span>
<span class="line"><span> │        │            └→ To Approve (big orders, when approval is on)</span></span>
<span class="line"><span> └────────┴→ Canceled → Set to Draft → RFQ</span></span></code></pre></div><ol><li><strong>Draft the request.</strong> Create an RFQ with a vendor and products. See <a href="./quotations.html">Requests for quotation</a>.</li><li><strong>Send it.</strong> Email the vendor or print the PDF. The status becomes <strong>RFQ Sent</strong>.</li><li><strong>Confirm it.</strong> Click <strong>Confirm Order</strong>. The RFQ becomes a purchase order. See <a href="./purchase-orders.html">Purchase orders</a>.</li><li><strong>Receive the goods.</strong> The receipt waits in Inventory. See <a href="./../../inventories/operations/receipts.html">Receipts</a>.</li><li><strong>Pay the bill.</strong> Create the vendor bill from what you received. See <a href="./vendor-bills.html">Vendor bills</a>.</li></ol><p>The same record changes status. You never copy data from one document to the next.</p><h2 id="statuses" tabindex="-1">Statuses <a class="header-anchor" href="#statuses" aria-label="Permalink to &quot;Statuses&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>What it means</th></tr></thead><tbody><tr><td><strong>RFQ</strong></td><td>A draft. Nothing is sent. You can edit everything.</td></tr><tr><td><strong>RFQ Sent</strong></td><td>The vendor received the request by email or you printed it.</td></tr><tr><td><strong>To Approve</strong></td><td>The order is above the approval amount and waits for an approver.</td></tr><tr><td><strong>Purchase Order</strong></td><td>The order is confirmed. The receipt is planned.</td></tr><tr><td><strong>Locked</strong></td><td>The order is confirmed and protected from changes.</td></tr><tr><td><strong>Canceled</strong></td><td>The order is stopped. You can set it back to draft.</td></tr></tbody></table><h2 id="two-extra-statuses-on-every-order" tabindex="-1">Two extra statuses on every order <a class="header-anchor" href="#two-extra-statuses-on-every-order" aria-label="Permalink to &quot;Two extra statuses on every order&quot;">​</a></h2><p>Each order also tracks two side statuses, shown as list columns and filters.</p><ul><li><strong>Receipt status:</strong> <strong>Nothing To Receive</strong>, <strong>Pending</strong>, <strong>Partially Received</strong>, <strong>Fully Received</strong>.</li><li><strong>Billing status:</strong> nothing to bill yet, waiting for bills, or fully billed.</li></ul><h2 id="behind-the-scenes" tabindex="-1">Behind the scenes <a class="header-anchor" href="#behind-the-scenes" aria-label="Permalink to &quot;Behind the scenes&quot;">​</a></h2><p>Every order gets a number with the <strong>PO/</strong> prefix, such as <strong>PO/3</strong>. RFQs and purchase orders share the same numbers.</p><p>When you confirm an order, Aureus plans a receipt in the Inventory app, for example <strong>WH/IN/11</strong>. Only products of the goods type create a receipt. When you create a bill, Aureus bills the quantity you received, minus what you already billed.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Receipts need the Inventory app. Without it, orders still work, but no receipt is planned.</p></div><h2 id="settings-that-change-the-flow" tabindex="-1">Settings that change the flow <a class="header-anchor" href="#settings-that-change-the-flow" aria-label="Permalink to &quot;Settings that change the flow&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Effect</th></tr></thead><tbody><tr><td><strong>Purchase Order Approval</strong></td><td>Big orders stop at <strong>To Approve</strong>.</td></tr><tr><td><strong>Lock Confirmed Orders</strong></td><td>Confirmed orders go straight to <strong>Locked</strong>.</td></tr><tr><td><strong>Purchase Agreements</strong></td><td>Adds the <strong>Purchase Agreements</strong> menu and the <strong>Agreement</strong> field.</td></tr></tbody></table><p>Change them in <code>Purchase → Settings → Manage Orders</code>. See <a href="./../get-started/purchase-settings.html">Purchase settings</a>.</p><h2 id="pages-in-this-section" tabindex="-1">Pages in this section <a class="header-anchor" href="#pages-in-this-section" aria-label="Permalink to &quot;Pages in this section&quot;">​</a></h2><ul><li><a href="./quotations.html">Requests for quotation</a>: create, send and confirm an RFQ.</li><li><a href="./purchase-orders.html">Purchase orders</a>: approval, lock, cancel and quantity rules.</li><li><a href="./../../inventories/operations/receipts.html">Receipts</a>: the goods that arrive (in the Inventory guide).</li><li><a href="./vendor-bills.html">Vendor bills</a>: billing what you received.</li><li><a href="./blanket-orders.html">Blanket orders</a>: agree a total quantity and price with a vendor.</li><li><a href="./purchase-templates.html">Purchase templates</a>: reuse the same lines on new RFQs.</li><li><a href="./purchase-agreements.html">Purchase agreements</a>: how both kinds share one list.</li><li><a href="./../../../getting-started/contacts/contacts.html">Contacts</a>: create vendors and set their purchase terms.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../">Purchase overview</a></li><li><a href="./../get-started/first-steps.html">First steps</a></li><li><a href="./../../inventories/operations/receipts.html">Inventory receipts</a></li></ul>`,24)]))}const g=t(o,[["render",n]]);export{u as __pageData,g as default};
